#include <bits/stdc++.h>
using namespace std;

long sq(long a) {
    return a * a;
}

long distSq(long ax, long ay, long bx, long by) {
    return sq(ax - bx) + sq(ay - by);
}

struct Point {
    long x1, x2, x3, x4, x5;

    Point(long a1, long a2, long a3, long a4, long a5) : x1(a1), x2(a2), x3(a3), x4(a4), x5(a5) {}

    long lenSq() const {
        return sq(x1) + sq(x2) + sq(x3) + sq(x4) + sq(x5);
    }

    long prod(const Point& other) const {
        return x1 * other.x1 + x2 * other.x2 + x3 * other.x3 + x4 * other.x4 + x5 * other.x5;
    }

    Point sub(const Point& other) const {
        return Point(x1 - other.x1, x2 - other.x2, x3 - other.x3, x4 - other.x4, x5 - other.x5);
    }
};

bool check(const vector<Point>& points, int i) {
    const Point& ith = points[i];
    int n = points.size();
    for (int j = 0; j < n; ++j) {
        if (j == i) continue;
        for (int k = 0; k < n; ++k) {
            if (k == i || k == j) continue;
            Point x = points[j].sub(ith);
            Point y = points[k].sub(ith);
            if (x.prod(y) > 0) {
                return false;
            }
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 11) {
        cout << "0\n";
        return 0;
    }
    vector<Point> points;
    points.reserve(n);
    for (int i = 0; i < n; ++i) {
        long a1, a2, a3, a4, a5;
        cin >> a1 >> a2 >> a3 >> a4 >> a5;
        points.emplace_back(a1, a2, a3, a4, a5);
    }
    vector<int> ret;
    for (int i = 0; i < n; ++i) {
        if (check(points, i)) {
            ret.push_back(i + 1);
        }
    }
    cout << ret.size() << "\n";
    for (int x : ret) {
        cout << x << "\n";
    }
    return 0;
}

